{"implementation": "def solve(case):
    nodes = case["nodes"]
    required_symbols = set(case["required_symbols"])

    # Build id -> node lookup
    node_by_id = {n["id"]: n for n in nodes}

    def get_ancestors(node_id):
        """Return all node ids from node_id up to root, inclusive."""
        path = []
        current = node_id
        while current is not None:
            path.append(current)
            current = node_by_id[current]["parent"]
        return path

    # Always keep non-removable nodes and their full ancestor paths
    kept = set()
    for node in nodes:
        if not node["removable"]:
            for anc_id in get_ancestors(node["id"]):
                kept.add(anc_id)

    # Track which symbols are already covered by the kept set
    covered = {node_by_id[nid]["symbol"] for nid in kept}

    # For each required symbol not yet covered, select the highest-utility
    # removable node that carries that symbol, then keep it and its ancestors
    for symbol in required_symbols:
        if symbol not in covered:
            candidates = [
                n for n in nodes
                if n["symbol"] == symbol and n["removable"]
            ]
            if candidates:
                best = max(candidates, key=lambda n: n["utility"])
                for anc_id in get_ancestors(best["id"]):
                    kept.add(anc_id)
                covered.add(symbol)

    return {"kept_nodes": sorted(kept)}
"}
